{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 자신의 폭언을 '기강 잡기'로 규정하며, 자신이 특별한 위치에 있으므로 부하 직원을 향한 강한 발언이 정당하다고 보는 시각의 기저에 '보통 사람들에게 적용되는 규칙이 나에게 적용되어서는 안 된다'는 핵심 신념이 작동하고 있음. 성장 배경에서 어머니가 반복적으로 '너는 다른 애들과 급이 다르다'고 말한 경험이 이 신념을 형성함."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '기강 잡은 거'라고 주장하는 것은 '압도적 성과를 내면 사람들은 내 방식에 토를 달지 못한다'는 가정이 작동하기 때문. 상황 사례 /situations/1에서 신입 직원의 규정 지적에 '실적 내고 나서 얘기해'라고 면박을 준 패턴과 동일하게, 현재도 성과가 모든 것을 정당화한다는 가정이 발화되고 있음."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 문제를 '나약한 요즘 애들'과 '유난스러운 회사' 탓으로 돌리고, 자신의 폭언을 '기강 잡기'로 재정의하는 것은 관계 문제의 원인을 상대의 나약함·능력 부족에서 찾는 대응 방식과 직접 연결됨. /situations/1에서 신입 직원의 지적을 '영업을 모르는 사람'으로 치환한 것과 같은 패턴."
    },
    {
      "trait_id": "/coping_strategies/2",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 인사팀의 폭언 판정과 상담 프로그램 권고를 수용하지 않는 것은 회사 절차·규정과 자신의 방식이 부딪힐 때 실적을 방패로 삼는 대응 방식과 연결됨. /situations/0에서 인사팀 통보에 '실적 한 번 못 내 본 것들이'라고 반발한 것과 동일한 구조."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '인사팀에서 오라고 해서 온 거니까요'라며 상담 자체를 형식적으로 임하는 태도는, 자신이 통제할 수 없는 자리(상담·평가)를 '시간 낭비'로 규정하는 대응 방식과 직접 관련됨."
    }
  ]
}

